import { cn } from '@/react/lib/cn'

// Progress as a bar (console2.css .v2-meter): a 4px hairline-grey track with an ink fill. `tone="top"` fills it red,
// for the largest share in a list (the bill's amounts); `tone="rest"` in neutral-500, for what the rest add up to.
// `label` names it for screen readers (role meter); `decorative` hides it when the row's text already says it, such
// as a share bar in a table. `live` eases the fill linearly as the value moves (a job's progress), on transform from the
// left, still for reduced motion.
export interface MeterProps { value: number, max?: number, label?: string, tone?: 'default' | 'top' | 'rest', decorative?: boolean, live?: boolean, className?: string }

const FILL = { default: 'bg-surface-inverse', top: 'bg-edge-accent', rest: 'bg-ds-neutral-500' }

export function Meter({ value, max = 100, label, tone = 'default', decorative, live, className }: MeterProps) {
  const share = Math.max(0, Math.min(1, value / (max || 1)))
  return (
    <>
      <style href="ds-meter" precedence="ds">{css}</style>
      <div
        data-ds="meter"
        className={cn('block h-1 bg-edge', className)}
        role={decorative ? undefined : 'meter'}
        aria-hidden={decorative || undefined}
        aria-label={decorative ? undefined : label}
        aria-valuemin={decorative ? undefined : 0}
        aria-valuemax={decorative ? undefined : max}
        aria-valuenow={decorative ? undefined : value}
      >
        <span className={cn('block h-full', [FILL[tone], live && 'ds-meter-live'])} style={live ? { transform: `scaleX(${share})` } : { width: `${share * 100}%` }} />
      </div>
    </>
  )
}

export default Meter

const css = `
/* A job's progress moves on its own clock, so it eases linearly (console2.css .v2-meter[data-state]). */
.ds-meter-live { width: 100%; transform-origin: left; transition: transform var(--ds-duration-progress) linear; }
@media (prefers-reduced-motion: reduce) { .ds-meter-live { transition: none; } }
`

import { cn } from '@/react/lib/cn'

// Steps as squares (SetupMeter.vue, after the overview's pixel meters): 6px squares 2px apart, done steps ink, the next
// one red, the rest an empty hairline. A picture: put the words beside it ("2 of 4 done").
export interface StepMeterProps { steps: boolean[], className?: string }

export function StepMeter({ steps, className }: StepMeterProps) {
  const next = steps.findIndex(f => !f)
  return (
    <span data-ds="step-meter" className={cn('inline-flex gap-0.5', className)} aria-hidden="true">
      {steps.map((done, i) => (
        <i key={i} className={cn('size-1.5 border', done ? 'border-surface-inverse bg-surface-inverse' : i === next ? 'border-edge-accent bg-edge-accent' : 'border-edge-strong')} />
      ))}
    </span>
  )
}

export default StepMeter

// Joins class names, skipping falsy ones: cn('a', on && 'b', ['c', undefined]). It does not merge conflicting
// utilities (no tailwind-merge), as Vue's class binding does not: the library's classes are written not to compete,
// and a className from the caller is appended after them, as Vue appends a fallthrough class.
export type ClassValue = string | false | null | undefined | 0 | ClassValue[]

export function cn(...values: ClassValue[]): string {
	const out: string[] = []
	for (const v of values) {
		if (!v) continue
		if (Array.isArray(v)) {
			const s = cn(...v)
			if (s) out.push(s)
		}
		else out.push(v)
	}
	return out.join(' ')
}

import { html } from 'lit'
import { ifDefined } from 'lit/directives/if-defined.js'
import { styleMap } from 'lit/directives/style-map.js'
import { DsElement, define } from '@/elements/lib/element'
import styles from 'virtual:tw'

// Meter.vue as <conare-meter>: progress as a bar (console2.css .v2-meter): a 4px hairline-grey track with an ink fill.
// `tone="top"` fills it red, for the largest share in a list (the bill's amounts); `tone="rest"` in neutral-500, for
// what the rest add up to. `label` names it for screen readers (role meter); `decorative` hides it when the row's text
// already says it, such as a share bar in a table. `live` eases the fill linearly as the value moves (a job's
// progress), on transform from the left, still for reduced motion.

const FILL = { default: 'bg-surface-inverse', top: 'bg-edge-accent', rest: 'bg-ds-neutral-500' }

/** @summary Progress as a bar. */
export class Meter extends DsElement {
	static styles = [DsElement.styles, styles]
	static properties = { value: { type: Number }, max: { type: Number }, label: {}, tone: {}, decorative: { type: Boolean }, live: { type: Boolean } }

	value = 0
	max = 100
	/** The name for assistive tech. */
	label?: string
	tone: 'default' | 'top' | 'rest' = 'default'
	/** Hidden from assistive tech (the row's text says it). */
	decorative = false
	/** Ease the fill as the value moves. */
	live = false

	render() {
		const share = Math.max(0, Math.min(1, this.value / (this.max || 1)))
		const d = this.decorative
		return html`<div data-ds="meter" class="block h-1 bg-edge" role=${ifDefined(d ? undefined : 'meter')} aria-hidden=${ifDefined(d ? 'true' : undefined)} aria-label=${ifDefined(d ? undefined : this.label)} aria-valuemin=${ifDefined(d ? undefined : '0')} aria-valuemax=${ifDefined(d ? undefined : String(this.max))} aria-valuenow=${ifDefined(d ? undefined : String(this.value))}><span class=${['block h-full', FILL[this.tone] ?? FILL.default, this.live ? 'ds-meter-live' : ''].join(' ')} style=${styleMap(this.live ? { transform: `scaleX(${share})` } : { width: `${share * 100}%` })}></span></div>`
	}
}

define('meter', Meter)

/* Meter.vue's <style>, as it is. */
/* A job's progress moves on its own clock, so it eases linearly (console2.css .v2-meter[data-state]). */
.ds-meter-live { width: 100%; transform-origin: left; transition: transform var(--ds-duration-progress) linear; }
@media (prefers-reduced-motion: reduce) { .ds-meter-live { transition: none; } }

import { html } from 'lit'
import { DsElement, define } from '@/elements/lib/element'
import styles from 'virtual:tw'

// StepMeter.vue as <conare-step-meter>: steps as squares (SetupMeter.vue, after the overview's pixel meters): 6px
// squares 2px apart, done steps ink, the next one red, the rest an empty hairline. A picture: put the words beside it
// ("2 of 4 done"). `steps` is a JSON attribute (steps='[true,true,false,false]') or a property.

/** @summary Steps as squares. */
export class StepMeter extends DsElement {
	static styles = [DsElement.styles, styles]
	static properties = { steps: { type: Array } }

	steps: boolean[] = []

	render() {
		const next = this.steps.findIndex((f) => !f)
		return html`<span data-ds="step-meter" class="inline-flex gap-0.5" aria-hidden="true">${this.steps.map((done, i) => html`<i class=${['size-1.5 border', done ? 'border-surface-inverse bg-surface-inverse' : i === next ? 'border-edge-accent bg-edge-accent' : 'border-edge-strong'].join(' ')}></i>`)}</span>`
	}
}

define('step-meter', StepMeter)
